/** Aplica uma resposta da API: mural, contagem e travas do formulário. */
function aplicar(resposta){
  const r = resposta || {};
  if(Array.isArray(r.mural)){ ultimoMural = r.mural; renderMural(r.mural); }
  capacidade = normalizarCapacidade(r.capacidade) ||
               (Array.isArray(r.mural) ? capacidadeDoMural(r.mural) : capacidade);
  renderCapacidade();
  atualizarTrava();
}

